--
-- Name: projectsummary; Type: VIEW; Schema: gridline; Owner: -
--

CREATE VIEW gridline.projectsummary AS
 SELECT p.projectid,
    p.projectno,
    p.projectname,
    p.stage,
    p.clientname,
    p.projecttype,
    p.city,
    p.statecode,
    p.biddueon,
    v.versionid AS primaryversionid,
    v.versionno AS primaryversionno,
    v.versionlabel AS primaryversionlabel,
    v.grossarea,
    ( SELECT count(*) AS count
           FROM gridline.projectversion x
          WHERE (x.projectid = p.projectid)) AS versions,
    ( SELECT count(*) AS count
           FROM gridline.trade t
          WHERE ((t.versionid = v.versionid) AND (t.archivedat IS NULL))) AS trades,
    ( SELECT count(*) AS count
           FROM gridline.trade t
          WHERE ((t.versionid = v.versionid) AND (t.archivedat IS NULL) AND (EXISTS ( SELECT 1
                   FROM gridline.bid b
                  WHERE ((b.tradeid = t.tradeid) AND b.iscarried AND (b.archivedat IS NULL)))))) AS tradescarried,
    ( SELECT sum(COALESCE(t.carriedvalue, t.lowestvalue)) AS sum
           FROM gridline.trade t
          WHERE ((t.versionid = v.versionid) AND (t.archivedat IS NULL))) AS tradestotal,
    ( SELECT r.amount
           FROM gridline.rollupline r
          WHERE ((r.versionid = v.versionid) AND (r.linename = 'Contract total'::text))) AS contracttotal,
    p.companyid,
    p.estimatorid,
    p.createdat,
    p.changedat
   FROM (gridline.project p
     LEFT JOIN gridline.projectversion v ON (((v.projectid = p.projectid) AND v.isprimary)))
  WHERE (p.archivedat IS NULL);


--
-- Name: projecttrades; Type: VIEW; Schema: gridline; Owner: -
--

CREATE VIEW gridline.projecttrades AS
 SELECT p.projectid,
    p.projectno,
    p.projectname,
    v.versionid,
    v.versionno,
    v.isprimary AS isprimaryversion,
    t.tradeid,
    t.csicode,
    t.tradename,
    t.budgetvalue AS budget,
    t.lowestvalue AS lowest,
    t.carriedvalue,
    cb.biddername AS carriedbidder,
    ( SELECT count(*) AS count
           FROM gridline.bid b
          WHERE ((b.tradeid = t.tradeid) AND (b.archivedat IS NULL))) AS bids,
    t.plugamount,
    t.clientnote,
    t.teamnote
   FROM (((gridline.trade t
     JOIN gridline.projectversion v ON ((v.versionid = t.versionid)))
     JOIN gridline.project p ON ((p.projectid = v.projectid)))
     LEFT JOIN gridline.bid cb ON (((cb.tradeid = t.tradeid) AND cb.iscarried AND (cb.archivedat IS NULL))))
  WHERE (t.archivedat IS NULL);


