--
-- Name: scopeanswers; Type: VIEW; Schema: gridline; Owner: -
--

CREATE VIEW gridline.scopeanswers AS
 SELECT p.projectname,
    v.versionno,
    t.tradeid,
    t.csicode,
    t.tradename,
    l.lineid,
    l.section,
    l.sortkey,
    l.linetext,
    l.desired,
    b.bidid,
    chr((64 + b.laneno)) AS lane,
    b.biddername,
    COALESCE((a.kind)::text, 'blank'::text) AS answerkind,
    a.amount,
    a.answertext,
    a.cellcolour,
    a.source
   FROM (((((gridline.scopeline l
     JOIN gridline.trade t ON ((t.tradeid = l.tradeid)))
     JOIN gridline.projectversion v ON ((v.versionid = t.versionid)))
     JOIN gridline.project p ON ((p.projectid = v.projectid)))
     JOIN gridline.bid b ON (((b.tradeid = t.tradeid) AND (b.archivedat IS NULL))))
     LEFT JOIN gridline.scopeanswer a ON (((a.lineid = l.lineid) AND (a.bidid = b.bidid))))
  WHERE ((l.archivedat IS NULL) AND (NOT l.isheading));


