--
-- Name: tradebenchmark; Type: VIEW; Schema: gridline; Owner: -
--

CREATE VIEW gridline.tradebenchmark AS
 SELECT t.csicode,
    p.projecttype,
    count(*) AS projects,
    round(min((t.carriedvalue / (NULLIF(v.grossarea, 0))::numeric)), 2) AS lowpersf,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY (((t.carriedvalue / (NULLIF(v.grossarea, 0))::numeric))::double precision)))::numeric, 2) AS medianpersf,
    round(max((t.carriedvalue / (NULLIF(v.grossarea, 0))::numeric)), 2) AS highpersf,
    p.companyid
   FROM ((gridline.trade t
     JOIN gridline.projectversion v ON (((v.versionid = t.versionid) AND v.isprimary)))
     JOIN gridline.project p ON ((p.projectid = v.projectid)))
  WHERE ((t.archivedat IS NULL) AND (t.carriedvalue > (0)::numeric) AND (v.grossarea > 0) AND (p.stage = ANY (ARRAY['submitted'::gridline.projectstage, 'awarded'::gridline.projectstage, 'lost'::gridline.projectstage, 'bidding'::gridline.projectstage])))
  GROUP BY t.csicode, p.projecttype, p.companyid;


