--
-- Name: tradebids; Type: VIEW; Schema: gridline; Owner: -
--

CREATE VIEW gridline.tradebids AS
 SELECT p.projectid,
    p.projectno,
    p.projectname,
    v.versionid,
    v.versionno,
    v.isprimary AS isprimaryversion,
    t.tradeid,
    t.csicode,
    t.tradename,
    b.bidid,
    b.laneno,
    chr((64 + b.laneno)) AS lane,
    b.biddername,
    tp.companyname,
    b.state,
    b.isposted,
    b.iscarried,
    b.baseamount,
    b.scopeadjustments,
    b.totalamount,
        CASE
            WHEN b.isposted THEN rank() OVER (PARTITION BY t.tradeid, b.isposted ORDER BY b.totalamount)
            ELSE NULL::bigint
        END AS pricerank
   FROM ((((gridline.bid b
     JOIN gridline.trade t ON ((t.tradeid = b.tradeid)))
     JOIN gridline.projectversion v ON ((v.versionid = t.versionid)))
     JOIN gridline.project p ON ((p.projectid = v.projectid)))
     LEFT JOIN gridline.tradepartner tp ON ((tp.partnerid = b.partnerid)))
  WHERE ((t.archivedat IS NULL) AND (b.archivedat IS NULL));


