--
-- Name: whoishere; Type: VIEW; Schema: gridline; Owner: -
--

CREATE VIEW gridline.whoishere AS
 SELECT p.connectionid,
    p.projectid,
    p.versionid,
    p.pagekey,
    p.focuskind,
    p.focuskey,
    p.activity,
    u.userid,
    ((u.givenname || ' '::text) || u.familyname) AS personname,
    u.initials,
    u.colour,
    p.heartbeatat
   FROM (gridline.presence p
     JOIN gridline.appuser u ON ((u.userid = p.userid)))
  WHERE (p.heartbeatat > (now() - '00:00:45'::interval));


